// secretRule builds a Secrets catalog entry, which is always a Vulnerability with the Security quality
// and pattern detection; only the metadata and examples vary between detectors.
func secretRule(key, name string, sev shared.Severity, cwe, provider, desc, why, source, compliant, noncompliant string) rule.Rule {
	return rule.Rule{
		Key: rule.Key(key), Name: name, Language: "Secrets", Type: rule.TypeVulnerability, Qualities: []rule.Quality{rule.QualitySecurity},
		DefaultSeverity: sev, Tags: []string{"credentials", provider}, CWE: []string{cwe}, OWASP: []string{"A07:2021"}, Detection: rule.DetectionPattern,
		Description:         desc,
		Rationale:           why + "\n\nSource: " + source,
		Remediation:         "Remove the hardcoded credential, rotate it, and provide it at runtime via an environment variable or a secrets manager.",
		CompliantExample:    compliant,
		NoncompliantExample: noncompliant,
		RemediationEffort:   15,
	}
}
